10	// TestSnapshotRecordEntriesCaseVariantsAreCorrupt proves that a saved snapshot
11	// record whose top-level entries field is spelled with any casing other than
12	// exactly "entries" is corruption for every operation that reads saved
13	// snapshots. The variant may appear alone or beside the standard field, in
14	// either order, with identical or different content, empty or not — the
15	// outcome is always a "snapshot <full name> is corrupted" error naming the
16	// offending field, never a successful or partial result, and nothing in the
17	// repository changes: the current mapping, the corrupt record's bytes, all
18	// objects (including genuinely unreferenced ones), and existing outputs stay
19	// exactly as they were.
20	func TestSnapshotRecordEntriesCaseVariantsAreCorrupt(t *testing.T) {
21		goodDigest := digestOf("keep me")
22		rec := validRecordJSON("keep.txt", goodDigest, 7)
23		cases := map[string]struct {
24			fields    string // top-level fields following the name field
25			wantField string
26		}{
27			"variant alone with records": {
28				fields:    `"Entries":{"keep.txt":` + rec + `}`,
29				wantField: `"Entries"`,
30			},
31			"variant alone empty": {
32				fields:    `"ENTRIES":{}`,
33				wantField: `"ENTRIES"`,
34			},
35			"empty variant after standard field": {
36				fields:    `"entries":{"keep.txt":` + rec + `},"Entries":{}`,
37				wantField: `"Entries"`,
38			},
39			"empty variant before standard field": {
40				fields:    `"Entries":{},"entries":{"keep.txt":` + rec + `}`,
41				wantField: `"Entries"`,
42			},
43			"identical content in both spellings": {
44				fields:    `"entries":{"keep.txt":` + rec + `},"Entries":{"keep.txt":` + rec + `}`,
45				wantField: `"Entries"`,
46			},
47			"third casing beside standard field": {
48				fields:    `"entries":{"keep.txt":` + rec + `},"ENTRIES":{}`,
49				wantField: `"ENTRIES"`,
50			},
51			"unicode escape decoding to a variant": {
52				fields:    `"\u0045ntries":{},"entries":{"keep.txt":` + rec + `}`,
53				wantField: `"Entries"`,
54			},
55			"unicode escape inside the name": {
56				fields:    `"entr\u0049es":{}`,
57				wantField: `"entrIes"`,
58			},
59		}
60		for label, tc := range cases {
61			t.Run(label, func(t *testing.T) {
62				root := filepath.Join(t.TempDir(), "vault")
63				store := New(root)
64				if _, err := store.Put("keep.txt", writeInput(t, []byte("keep me"))); err != nil {
65					t.Fatal(err)
66				}
67				if _, err := store.CreateSnapshot("good"); err != nil {
68					t.Fatal(err)
69				}
70				// A genuinely unreferenced object: even this must survive GC
71				// while a corrupt snapshot record exists.
72				extra := []byte("extra unreferenced content")
73				if _, err := store.Put("extra.txt", writeInput(t, extra)); err != nil {
74					t.Fatal(err)
75				}
76				extraObject := objectPathOf(root, extra)
77				if err := store.RestoreSnapshot("good"); err != nil {
78					t.Fatal(err)
79				}
80	
81				record := `{"name":"releases/corrupt",` + tc.fields + `}`
82				recordPath := filepath.Join(root, "snapshots", "releases", "corrupt.json")
83				if err := os.MkdirAll(filepath.Dir(recordPath), 0o755); err != nil {
84					t.Fatal(err)
85				}
86				if err := os.WriteFile(recordPath, []byte(record), 0o644); err != nil {
87					t.Fatal(err)
88				}
89				assertCorrupt := func(op string, err error) {
90					t.Helper()
91					if err == nil {
92						t.Fatalf("%s succeeded over a corrupt snapshot record", op)
93					}
94					msg := err.Error()
95					if !strings.Contains(msg, `snapshot "releases/corrupt" is corrupted`) {
96						t.Fatalf("%s error %q does not identify the corrupt snapshot by its full name", op, msg)
97					}
98					if !strings.Contains(msg, tc.wantField) {
99						t.Fatalf("%s error %q does not name the offending field %s", op, msg, tc.wantField)
100					}
101				}
102	
103				// Restore: fails and the current mapping is unchanged.
104				assertCorrupt("restore", store.RestoreSnapshot("releases/corrupt"))
105				entries, err := store.List()
106				if err != nil || len(entries) != 1 || entries[0].Name != "keep.txt" {
107					t.Fatalf("failed restore changed the current mapping: entries=%+v err=%v", entries, err)
108				}
109	
110				// List: fails with no partial snapshot list.
111				infos, err := store.ListSnapshots()
112				assertCorrupt("list snapshots", err)
113				if infos != nil {
114					t.Fatalf("list returned partial snapshots: %+v", infos)
115				}
116	
117				// Export: fails and creates no package.
118				output := filepath.Join(t.TempDir(), "pkg.json")
119				_, err = store.ExportSnapshot("releases/corrupt", "", output)
120				assertCorrupt("export", err)
121				if _, err := os.Stat(output); !os.IsNotExist(err) {
122					t.Fatalf("failed export created a package: %v", err)
123				}
124	
125				// Export over an existing output: content and permissions stay
126				// exactly as they were.
127				existing := filepath.Join(t.TempDir(), "existing.json")
128				if err := os.WriteFile(existing, []byte("previous output"), 0o640); err != nil {
129					t.Fatal(err)
130				}
131				_, err = store.ExportSnapshot("releases/corrupt", "", existing)
132				assertCorrupt("export over existing output", err)
133				got, err := os.ReadFile(existing)
134				if err != nil || string(got) != "previous output" {
135					t.Fatalf("failed export altered the existing output: content=%q err=%v", got, err)
136				}
137				if info, err := os.Stat(existing); err != nil || info.Mode().Perm() != 0o640 {
138					t.Fatalf("failed export changed the existing output's permissions: mode=%v err=%v", info.Mode(), err)
139				}
140	
141				// Incremental export using the corrupt snapshot as its base fails
142				// and creates no package either.
143				deltaOut := filepath.Join(t.TempDir(), "delta.json")
144				_, err = store.ExportSnapshot("good", "releases/corrupt", deltaOut)
145				assertCorrupt("incremental export", err)
146				if _, err := os.Stat(deltaOut); !os.IsNotExist(err) {
147					t.Fatalf("failed incremental export created a package: %v", err)
148				}
149	
150				// GC, dry run and real: both fail before deleting anything, not
151				// even the genuinely unreferenced object.
152				_, err = store.GC(true)
153				assertCorrupt("dry-run gc", err)
154				_, err = store.GC(false)
155				assertCorrupt("gc", err)
156				if got, err := os.ReadFile(extraObject); err != nil || string(got) != string(extra) {
157					t.Fatalf("gc touched the unreferenced object: content=%q err=%v", got, err)
158				}
159	
160				// The corrupt record bytes are preserved exactly.
161				got, err = os.ReadFile(recordPath)
162				if err != nil {
163					t.Fatal(err)
164				}
165				if string(got) != record {
166					t.Fatalf("snapshot record was rewritten\nwas: %s\nnow: %s", record, got)
167				}
168			})
169		}
170	}
