172	// TestSnapshotRecordExactSpellingAccepted covers the snapshot records that
173	// must keep working: the standard field written through Unicode escapes, an
174	// explicitly empty entries mapping, and artifact names that merely resemble
175	// the field name — the rule applies only to the top-level mapping field.
176	func TestSnapshotRecordExactSpellingAccepted(t *testing.T) {
177		goodDigest := digestOf("keep me")
178		rec := validRecordJSON("keep.txt", goodDigest, 7)
179		cases := map[string]struct {
180			record string
181			want   int
