266	// the complete artifact name. Artifact rows are returned only after the whole
267	// current mapping proves complete, unambiguous, and legal: it is loaded with
268	// the same strict rules upload, verify, gc, and snapshot creation apply (one
269	// complete JSON object with an explicitly present, object-valued entries
270	// mapping — a genuine {"entries":{}} is a healthy empty repository and lists
271	// zero rows; a bare null, an empty {}, a missing or null entries field, a
272	// non-object entries value, a truncated document, trailing content, or any
273	// duplicate key at any level, including a name written directly and again
274	// through Unicode escapes, is corruption), and every record must be keyed by
275	// its recorded name with a legal name, a 64-character lowercase-hex digest,
276	// and a non-negative size. A single bad record fails the whole listing even
277	// when every other record is healthy; no partial set of names is returned and
278	// the bad record is never skipped.
279	//
280	// On failure List returns nil and an error: "current index is corrupt: …"
281	// (naming the duplicated key or the offending mapping name) when the bytes are
282	// damaged, "current index cannot be read: …" when they cannot be read, and a
283	// not-initialized error when the repository or its index.json does not exist,
284	// which is never reported as an empty list. List reads only the current
285	// mapping: it never reads or verifies content objects and never reads
286	// snapshots, so a missing or damaged object or a damaged snapshot does not
287	// stop the legal current records from showing. List never rewrites the index,
288	// snapshots, or objects. The lock is shared, so lists run alongside downloads
289	// and verifies.
290	func (s *Store) List() ([]Entry, error) {
291		entries := []Entry{}
292		err := s.withLockOpts(false, false, func() error {
293			idx, err := s.loadStrictValidEntries()
294			if err != nil {
295				return err
296			}
297			keys := make([]string, 0, len(idx.Entries))
298			for key := range idx.Entries {
299				keys = append(keys, key)
300			}
301			sort.Strings(keys)
302			entries = make([]Entry, 0, len(keys))
303			for _, key := range keys {
304				entries = append(entries, idx.Entries[key])
305			}
306			return nil
307		})
308		if err != nil {
309			return nil, err
310		}
311		return entries, nil
312	}
313	
314	// Verify checks every entry of the current name mapping against its content
315	// object: the object must exist and its actual size and SHA-256 must match
316	// the recorded metadata. The mapping itself must be complete and unambiguous
317	// first: the index must be one complete JSON object with an explicitly
318	// present entries mapping (a true {"entries":{}} is a legitimate empty
319	// repository; null, a missing or null entries field, an array, truncated
320	// input, trailing content, or any duplicate key — including a name repeated
321	// through Unicode escapes — is corruption), and every record must pass the
322	// same validity checks downloads and gc apply (keyed by its recorded name, a
323	// legal name, a 64-character lowercase-hex digest, a non-negative size). A
324	// single malformed record fails the whole pass; bad records are never
325	// skipped to report success over the rest. Mapping problems are reported
326	// before any object is read, so index corruption is always distinguished
327	// from object damage.
328	//
329	// The whole pass — reading the mapping and checking every object it
330	// references — runs under one shared repository lock, so the mapping and the
331	// objects it points at cannot be replaced or collected by another process
332	// between the first read and the last check: an overwrite, snapshot restore,
333	// import, or gc either completes before the pass starts (and the pass
334	// observes the completed state) or waits until the pass ends. The lock is
335	// shared, so concurrent lists, downloads, and other verifies proceed
336	// alongside it. Verify never rewrites the mapping, snapshots, or objects,
337	// and never repairs damaged content; on the first failure it reports the
338	// cause and returns a zero count.
339	func (s *Store) Verify() (int, error) {
340		count := 0
341		err := s.withLock(false, func() error {
342			idx, err := s.loadStrictValidEntries()
343			if err != nil {
344				return err
345			}
346			entries := make([]Entry, 0, len(idx.Entries))
347			for _, entry := range idx.Entries {
348				entries = append(entries, entry)
349			}
350			// Sort by name so the first reported failure is deterministic.
351			sort.Slice(entries, func(i, j int) bool { return entries[i].Name < entries[j].Name })
352			for _, entry := range entries {
353				if err := s.verifyObject(entry); err != nil {
354					return fmt.Errorf("verify %q: %w", entry.Name, err)
355				}
356			}
357			count = len(entries)
358			return nil
359		})
360		if err != nil {
361			return 0, err
362		}
363		return count, nil
364	}
365	
366	// verifyObject checks that the content object for entry exists and that its
367	// actual size and SHA-256 match the recorded metadata.
368	func (s *Store) verifyObject(entry Entry) error {
369		file, err := os.Open(s.objectPath(entry.Digest))
370		if err != nil {
371			return err
372		}
373		hash := sha256.New()
374		size, copyErr := io.Copy(hash, file)
375		closeErr := file.Close()
376		if copyErr != nil || closeErr != nil {
377			return errors.New("read failed")
378		}
379		if size != entry.Size || hex.EncodeToString(hash.Sum(nil)) != entry.Digest {
380			return errors.New("content mismatch")
381		}
382		return nil
383	}
384	
385	func (s *Store) save(idx index) error {
386		data, err := json.MarshalIndent(idx, "", "  ")
387		if err != nil {
388			return err
389		}
390		data = append(data, '\n')
391		tmp, err := os.CreateTemp(s.root, ".index-*")
392		if err != nil {
393			return err
394		}
395		tmpName := tmp.Name()
396		defer os.Remove(tmpName)
397		if _, err := tmp.Write(data); err != nil {
398			tmp.Close()
399			return err
400		}
401		if err := tmp.Close(); err != nil {
402			return err
403		}
404		return os.Rename(tmpName, s.indexPath())
405	}
406	
407	func (s *Store) indexPath() string               { return filepath.Join(s.root, "index.json") }
408	func (s *Store) lockPath() string                { return filepath.Join(s.root, ".lock") }
409	func (s *Store) objectPath(digest string) string { return filepath.Join(s.root, "objects", digest) }
