package vault

import (
	"strings"
	"testing"
)

func d7() string { return digestOf("payload") }
func recFor() string {
	return validRecordJSON("keep.txt", d7(), 7)
}

func TestZZCaseVariants(t *testing.T) {
	d := d7()
	rec := recFor()
	obj := `"objects":[{"digest":"` + d + `","size":7,"data":"cGF5bG9hZA=="}]`
	cases := map[string]string{
		"variant alone Entries":         `"snapshot":{"name":"s","Entries":{"keep.txt":` + rec + `}}`,
		"variant alone ENTRIES empty":   `"snapshot":{"name":"s","ENTRIES":{}}`,
		"variant after standard":        `"snapshot":{"name":"s","entries":{"keep.txt":` + rec + `},"Entries":{}}`,
		"variant before standard":       `"snapshot":{"name":"s","Entries":{},"entries":{"keep.txt":` + rec + `}}`,
		"identical both":                `"snapshot":{"name":"s","entries":{"keep.txt":` + rec + `},"Entries":{"keep.txt":` + rec + `}}`,
		"unicode escape variant":        `"snapshot":{"name":"s","Entries":{},"entries":{"keep.txt":` + rec + `}}`,
		"escape inside":                 `"snapshot":{"name":"s","entrIes":{}}`,
		"base variant alone":            `"snapshot":{"name":"t","entries":{}},"base":{"name":"b","Entries":{}}`,
		"base variant beside":           `"snapshot":{"name":"t","entries":{}},"base":{"name":"b","entries":{},"ENTRIES":{}}`,
	}
	for label, body := range cases {
		doc := `{"format":"artifact-vault-snapshot","version":1,` + body + `,` + obj + `}`
		_, err := decodePackage([]byte(doc))
		if err == nil {
			t.Errorf("%s: ACCEPTED", label)
			continue
		}
		t.Logf("%s rejected: %v", label, err)
	}

	// Accepted cases
	ok := map[string]string{
		"standard escaped": `{"format":"artifact-vault-snapshot","version":1,"snapshot":{"name":"s","entries":{"keep.txt":` + rec + `}},"objects":[{"digest":"` + d + `","size":7,"data":"cGF5bG9hZA=="}]}`,
		"explicit empty":   `{"format":"artifact-vault-snapshot","version":1,"snapshot":{"name":"s","entries":{}},"objects":[]}`,
		"empty base":       `{"format":"artifact-vault-snapshot","version":1,"snapshot":{"name":"t","entries":{}},"base":{"name":"b","entries":{}},"objects":[]}`,
	}
	for label, doc := range ok {
		if _, err := decodePackage([]byte(doc)); err != nil {
			t.Errorf("%s: rejected: %v", label, err)
		}
	}

	// Missing/null/non-object still rejected
	for _, c := range []string{
		`{"format":"artifact-vault-snapshot","version":1,"snapshot":{"name":"s"},"objects":[]}`,
		`{"format":"artifact-vault-snapshot","version":1,"snapshot":{"name":"s","entries":null},"objects":[]}`,
		`{"format":"artifact-vault-snapshot","version":1,"snapshot":{"name":"s","entries":[1]},"objects":[]}`,
		`{"format":"artifact-vault-snapshot","version":1,"snapshot":null,"objects":[]}`,
		`{"format":"artifact-vault-snapshot","version":1,"snapshot":{"name":"s","entries":{}},"base":null,"objects":[]}`,
	} {
		if _, err := decodePackage([]byte(c)); err == nil {
			t.Errorf("ACCEPTED: %s", c)
		} else {
			t.Logf("rejected: %v", err)
		}
	}

	// Artifact literally named Entries must import fine
	recE := validRecordJSON("Entries", d, 7)
	doc := `{"format":"artifact-vault-snapshot","version":1,"snapshot":{"name":"s","entries":{"Entries":` + recE + `}},"objects":[{"digest":"` + d + `","size":7,"data":"cGF5bG9hZA=="}]}`
	pkg, err := decodePackage([]byte(doc))
