		t.Errorf("base error not specific: %v", err)
	}
	doc3 := `{"format":"artifact-vault-snapshot","version":1,"snapshot":{"name":"mytarget","Entries":{}},"objects":[]}`
	_, err = decodePackage([]byte(doc3))
	if err == nil || !strings.Contains(err.Error(), "target snapshot") || !strings.Contains(err.Error(), "mytarget") {
