		`"new.txt":` + validRecordJSON("new.txt", dNew, int64(len(newData))) + `}},` +
		`"base":{"name":"base","Entries":{"keep.txt":` + validRecordJSON("keep.txt", dOld, 7) + `}},` +
		`"objects":[` + rawObjectRecord(newData) + `]}`

